alter table public.datasub_transactions add column if not exists product_id uuid references public.datasub_products(id), add column if not exists selling_price numeric, add column if not exists provider_cost numeric, add column if not exists routing_state text not null default 'CREATED', add column if not exists last_reconciled_at timestamptz;
alter table public.datasub_provider_attempts add column if not exists request_payload jsonb not null default '{}'::jsonb, add column if not exists provider_path text, add column if not exists is_ambiguous boolean not null default false, add column if not exists reconciled_at timestamptz;
create unique index if not exists idx_datasub_tx_user_client_key on public.datasub_transactions(user_id,((metadata->>'client_idempotency_key'))) where metadata ? 'client_idempotency_key';
create or replace function public.reserve_datasub_wallet(p_user uuid,p_transaction uuid,p_amount numeric,p_reference text) returns boolean language plpgsql security definer set search_path=public as $$ declare b numeric; begin if p_user is null or p_amount<=0 then return false; end if; select balance into b from public.datasub_wallets where user_id=p_user for update; if b is null or b<p_amount then return false; end if; update public.datasub_wallets set balance=balance-p_amount,updated_at=now() where user_id=p_user; insert into public.wallet_ledger(user_id,transaction_id,entry_type,amount,reference) values(p_user,p_transaction,'reserve',p_amount,p_reference) on conflict(reference) do nothing; return true; end $$;
create or replace function public.refund_datasub_wallet(p_user uuid,p_transaction uuid,p_amount numeric,p_reference text) returns boolean language plpgsql security definer set search_path=public as $$ begin if exists(select 1 from public.wallet_ledger where reference=p_reference) then return true; end if; update public.datasub_wallets set balance=balance+p_amount,updated_at=now() where user_id=p_user; insert into public.wallet_ledger(user_id,transaction_id,entry_type,amount,reference) values(p_user,p_transaction,'refund',p_amount,p_reference); return true; end $$;
revoke all on function public.reserve_datasub_wallet(uuid,uuid,numeric,text) from public,anon,authenticated; revoke all on function public.refund_datasub_wallet(uuid,uuid,numeric,text) from public,anon,authenticated; grant execute on function public.reserve_datasub_wallet(uuid,uuid,numeric,text) to service_role; grant execute on function public.refund_datasub_wallet(uuid,uuid,numeric,text) to service_role;